        "filename": "domation_semantic_metrics.yaml & metric_resolver.ts",
        "description": "Định nghĩa chuẩn hóa Doanh thu thuần (chống đơn hủy & tách VAT), Qualified Lead và ROAS thực bằng hai CTE chống Fan-out Join, đi kèm hàm TypeScript ép AI truy vấn qua danh mục metric thay vì sinh SQL thô.",
        "code": "# 1) Semantic Metrics Registry (domation_semantic_metrics.yaml)\nversion: \"1.4\"\nmodels:\n  - name: finance_crm_orders\n    sql_table: erp_core.orders_clean\n    time_dimension: paid_at\n    always_filter: \"status NOT IN ('draft', 'cancelled', 'internal_test')\"\n    measures:\n      net_revenue_ex_vat:\n        label: \"Doanh thu thuần chưa VAT\"\n        synonyms: [\"doanh thu thuần\", \"net revenue\", \"doanh số thực chưa thuế\"]\n        expr: \"SUM(gross_amount_vnd / (1 + COALESCE(vat_rate, 0.08)) - refund_amount_vnd)\"\n        format: \"currency_vnd\"\n      qualified_orders_count:\n        label: \"Số đơn đặt cọc / chốt hợp lệ\"\n        expr: \"COUNT(DISTINCT order_id) FILTER (WHERE deposit_paid_vnd > 0)\"\n    dimensions: [\"branch_code\", \"sale_team\", \"campaign_id\", \"source_channel\"]\n\n  - name: meta_ads_daily\n    sql_table: marketing.meta_ad_spend_daily\n    time_dimension: spend_date\n    measures:\n      ad_spend_vnd:\n        label: \"Chi phí Meta Ads (VNĐ)\"\n        expr: \"SUM(spend_vnd)\"\n\ncomposite_metrics:\n  true_cash_roas:\n    label: \"ROAS Thực (Doanh thu thuần / Chi phí Ads)\"\n    synonyms: [\"roas thực\", \"hiệu suất doanh thu quảng cáo\"]\n    # Ép tính bằng CTE theo grain chung tránh lỗi nhân đôi dòng (Fan-out Join)\n    join_grain: [\"date_month\", \"campaign_id\"]\n    numerator: \"finance_crm_orders.net_revenue_ex_vat\"\n    denominator: \"meta_ads_daily.ad_spend_vnd\"\n    formula: \"COALESCE(num, 0) / NULLIF(den, 0)\"\n\n// 2) TypeScript Metric Resolver Tool (chặn LLM tự viết JOIN SQL tùy tiện)\nimport { z } from 'zod';\n\nconst MetricQuerySchema = z.object({\n  metrics: z.array(z.enum(['net_revenue_ex_vat', 'qualified_orders_count', 'ad_spend_vnd', 'true_cash_roas'])).min(1),\n  dimensions: z.array(z.enum(['date_month', 'branch_code', 'campaign_id', 'source_channel'])).max(3),\n  dateFrom: z.string().regex(/^\\d{4}-\\d{2}-\\d{2}$/),\n  dateTo: z.string().regex(/^\\d{4}-\\d{2}-\\d{2}$/),\n});\n\nexport async function executeSemanticQuery(rawArgs: unknown, ctx: { tenantId: string; allowedBranch?: string }) {\n  const req = MetricQuerySchema.parse(rawArgs);\n  // Biên dịch SQL tất định từ YAML Catalog + ép RLS theo tenantId & allowedBranch trên Read-Replica\n  const compiledSql = compileCteSafeSql(req, ctx);\n  return readReplicaPool.query(compiledSql.text, compiledSql.params);\n}"
